class Solution:
    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:
        T, n = temperatures, len(temperatures)
        ans = [0] * n
        for i in range(n - 2, -1, -1):
            j = i + 1
            while T[j] <= T[i] and ans[j]:
                j += ans[j]                 # 跳到比 T[j] 更热的那天
            if T[j] > T[i]:
                ans[i] = j - i
        return ans

