class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        int[] T = temperatures;
        int n = T.length;
        int[] ans = new int[n];
        for (int i = n - 2; i >= 0; i--) {
            int j = i + 1;
            while (T[j] <= T[i] && ans[j] != 0) {
                j += ans[j];                        // 跳到比 T[j] 更热的那天
            }
            if (T[j] > T[i]) {
                ans[i] = j - i;
            }
        }
        return ans;
    }
}

